const $ = (selector) => document.querySelector(selector);
const esc = (value) => String(value).replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages = [
  ['home','工作台','⌂','OVERVIEW'], ['devices','设备与连接','▯','DEVICES'],
  ['apps','应用管理','▦','APPLICATIONS'], ['schema','页面联调','↗','SCHEMA / INTENT'],
  ['logs','日志与异常','≡','LOGCAT'], ['media','截图与录屏','▣','CAPTURE'],
  ['files','文件与数据','▱','FILES'], ['network','网络联调','⇄','NETWORK'],
  ['diagnostics','性能与诊断','⌁','DIAGNOSTICS'], ['workflows','开发工作流','⋈','WORKFLOWS'],
  ['favorites','收藏','☆','FAVORITES'], ['history','执行历史','↶','HISTORY'], ['tasks','任务与产物','☷','TASKS'],
];
const devices = [
  {name:'Pixel 8',serial:'DEMO123',os:'Android 15',api:'35',kind:'USB',ready:true},
  {name:'Pixel 7 · 模拟器',serial:'emulator-5554',os:'Android 14',api:'34',kind:'LOCAL',ready:true},
  {name:'待授权设备',serial:'DEMO-LOCKED',os:'等待授权',api:'—',kind:'USB',ready:false},
];
const apps = [
  {name:'Demo App',pkg:'com.example.app',version:'2.6.0-debug',uid:'10248',debug:true},
  {name:'Demo App Staging',pkg:'com.example.app.staging',version:'2.6.0-rc1',uid:'10249',debug:true},
  {name:'系统设置',pkg:'com.android.settings',version:'15',uid:'1000',debug:false},
];
const state = {
  folder:'/sdcard/Download/',page:'home',device:devices[0],app:apps[0],connectionMode:'normal',schema:'',schemaHistory:[],historyIndex:null,draft:'',
  favorites:[{name:'商品详情',uri:'demo://product/detail?id=1024&source=dev'},{name:'WebView 联调',uri:'demo://web?url=https%3A%2F%2Fexample.com%2Fdebug'},{name:'登录页',uri:'demo://account/login?return=home'}],
  tasks:[{id:1,name:'应用日志采集',device:'DEMO123',status:'running',artifact:'logs/demo-app-143102.log',type:'log'}],
  results:[{name:'打开 schema',status:'success',device:'DEMO123',command:"adb -s DEMO123 shell am start -W -a android.intent.action.VIEW -d 'demo://product/detail?id=1024'",output:'Status: ok\nActivity: com.example.app/.ProductActivity\nTotalTime: 184\nComplete',time:'14:30:42',duration:'184 ms'}],
  history:[],mappings:[{device:'DEMO123',local:'8081',remote:'8081',direction:'reverse'}],logLevel:'all',logQuery:'',logPaused:false,
};
const commandInput = $('#command-input');
const time = () => new Date().toLocaleTimeString('zh-CN',{hour12:false});
let toastTimer, pendingDeviceAction = null, pickerIndex = 0, paletteIndex = 0, paletteItems = [], dockSchemaMode = false;
const availableDevices = () => state.connectionMode === 'none' ? [] : state.connectionMode === 'single' ? [devices[0]] : devices.filter(d=>d.ready);
const target = () => `${state.device.name} / ${state.app.pkg}`;
const tag = (status) => `<span class="tag ${status}">${{running:'进行中',saving:'保存中',success:'已完成',failed:'失败',cancelled:'已取消'}[status] || esc(status)}</span>`;
const button = (label,action,cls='') => `<button class="${cls}" data-action="${action}">${label}</button>`;
const panel = (title,body,code='') => `<section class="panel"><div class="panel-header"><h3>${title}</h3><span class="section-code">${code}</span></div>${body}</section>`;
const heading = (id,subtitle,actions='') => {const page=pages.find(p=>p[0]===id);return `<div class="page-heading"><div><div class="eyebrow">${page[3]}</div><h1>${page[1]}</h1><p class="page-subtitle">${subtitle}</p></div>${actions || '<span class="page-number">ADB / LOCAL</span>'}</div>`;};
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2600);}
function updateContext(){
  const available=availableDevices();
  if(available.length&&!available.some(d=>d.serial===state.device.serial))state.device=available[0];
  $('#available-count').textContent=available.length;
  $('#device-label').textContent=available.length?state.device.name:'未连接设备';$('#connection-label').textContent=available.length?state.device.kind:'—';
  $('#app-context').disabled=!available.length;
  $('#app-label').textContent=state.app.name+(state.app.debug?' / debug':'');
  $('#command-context-label').textContent=state.device.name.toUpperCase();
  $('#command-target').textContent=`${state.device.serial} · ${state.app.pkg}`;
  $('#task-count').textContent=state.tasks.filter(t=>t.status==='running').length;
}
function showPage(id){state.page=id;updateContext();$('#main').innerHTML=renderers[id]();$('#main').scrollTop=0;document.title=`${pages.find(p=>p[0]===id)[1]} · MyLogger`;}
function refresh(){const scroll=$('#main').scrollTop;updateContext();$('#main').innerHTML=renderers[state.page]();$('#main').scrollTop=scroll;}
function resultPanel(){const r=state.results[0];return panel('最近执行结果',r?`<div class="result-meta">${tag(r.status)}<span>${esc(r.device)}</span><span>${r.time}</span><span>${r.duration}</span></div><pre class="result-output">${esc(r.output)}</pre><div class="panel-body toolbar"><button class="text-button" data-result="0">查看完整结果 ↗</button></div>`:'<div class="result-placeholder">执行后，结果会显示在这里。</div>','OUTPUT');}
function devicePanel(){if(!availableDevices().length)return panel('当前连接','<div class="empty">没有可用设备。<br>连接 USB 或配置无线调试。</div>');return panel('当前连接',`<div class="panel-body"><div class="device-summary"><div class="device-illustration"></div><div><div class="device-name">${esc(state.device.name)}</div><div class="mono muted" style="font-size:10px">${state.device.serial}</div><div style="margin-top:8px"><span class="dot"></span> <span class="green" style="font-size:10px">已连接</span> <span class="tag">${state.device.kind}</span></div></div></div><div class="facts"><div class="fact"><small>系统版本</small><span>${state.device.os}</span></div><div class="fact"><small>API / ABI</small><span>${state.device.api} / arm64</span></div><div class="fact"><small>屏幕</small><span>1080 × 2400</span></div><div class="fact"><small>电量</small><span>86% · 充电中</span></div></div></div>`,'DEVICE');}
function actionRow(icon,title,description,command,action){return `<button class="action-row" data-action="${action}"><span class="action-icon">${icon}</span><span><strong>${title}</strong><small>${description}</small></span><code>${command}</code><span class="row-arrow">↗</span></button>`;}
function home(){return heading('home','设备已就绪。选择一个操作，开始本次调试。')+`<div class="columns"><div><div class="section-heading"><h2>常用操作</h2><span class="section-code">QUICK ACTIONS</span></div><section class="panel">${actionRow('↗','打开 schema','直达页面，支持收藏与输入历史','/schema','schema')}${actionRow('↓','安装并启动','覆盖安装 APK，保留应用数据','/install','install')}${actionRow('≡','抓取应用日志','按当前应用采集，多进程筛选','/log','logs')}${actionRow('▣','设备截图','保存当前画面，记录采集设备','/screenshot','screenshot')}${actionRow('⇄','本地服务联调','将设备端口映射到电脑服务','/reverse','network')}</section><div class="section-heading"><h2>最近使用的 schema</h2><button class="text-button" data-nav="favorites">全部收藏 ↗</button></div><section class="panel">${state.favorites.slice(0,2).map((f,i)=>`<button class="action-row" data-favorite="${i}"><span class="action-icon">☆</span><span style="min-width:0"><strong>${esc(f.name)}</strong><small class="mono" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:340px">${esc(f.uri)}</small></span><span class="row-arrow" style="margin-left:auto">↗</span></button>`).join('')}</section></div><div class="side-column">${devicePanel()}${panel('正在进行',state.tasks.filter(t=>t.status==='running').length?state.tasks.filter(t=>t.status==='running').map(t=>`<div class="mini-task"><div class="task-line"><span class="dot amber"></span>${esc(t.name)}<span style="margin-left:auto">${tag(t.status)}</span></div><div class="task-meta">${esc(t.device)} · ${t.type==='log'?'LOGCAT':'SCREENRECORD'}</div><div class="progress"><span></span></div><div class="toolbar"><span class="muted" style="font-size:10px">${esc(t.artifact)}</span><span class="spacer"></span><button class="small-button" data-stop="${t.id}">停止并保存</button></div></div>`).join(''):'<div class="result-placeholder">暂无进行中的任务</div>','LIVE TASKS')}${resultPanel()}</div></div>`;}
function devicePage(){return heading('devices','查看连接状态，所有设备操作都明确绑定目标。',`<div class="toolbar">${button('连接地址','connect')}${button('＋ 无线配对','pair')}</div>`)+panel('已发现的设备',`<div class="table-wrap"><table><thead><tr><th>设备 / SERIAL</th><th>系统</th><th>连接</th><th>状态</th><th>操作</th></tr></thead><tbody>${(state.connectionMode==='none'?[]:state.connectionMode==='single'?[devices[0]]:devices).map((d,i)=>`<tr><td>${d.name}<small>${d.serial}</small></td><td>${d.os}</td><td class="mono">${d.kind}</td><td><span class="${d.ready?'green':'amber-text'}">${d.ready?'可用':'未授权'}</span></td><td>${d.ready?`<button class="small-button" data-select-device="${i}">${d.serial===state.device.serial?'当前设备':'选择设备'}</button>`:'<span class="muted">请在设备上授权</span>'}</td></tr>`).join('')}</tbody></table></div>${state.connectionMode==='none'?'<div class="empty">没有可用设备。连接 USB 并在设备上允许调试。</div>':''}<div class="coverage toolbar"><label for="connection-scenario">连接场景预览</label><select id="connection-scenario"><option value="normal" ${state.connectionMode==='normal'?'selected':''}>多设备</option><option value="single" ${state.connectionMode==='single'?'selected':''}>单设备</option><option value="none" ${state.connectionMode==='none'?'selected':''}>无设备</option></select><span>用于检查连接状态下的交互</span></div>`)+`<div class="columns"><div>${devicePanel()}</div><div>${panel('设备操作',`<div class="panel-body"><div class="toolbar">${button('复制设备信息','copy-device')}${button('刷新连接','refresh-devices')}${button('重启设备','reboot','danger')}</div><div class="notice info">重启前会再次展示目标设备；ADB 服务重启与设备重启分开操作。</div></div>`)}</div></div>`;}
function appPage(){return heading('apps','应用、版本和进程信息放在一起，安装后可以直接启动。',button('＋ 安装 APK','install','primary'))+panel('已安装应用',`<div class="panel-body"><input id="app-filter" class="full" placeholder="搜索应用名称或包名…" aria-label="搜索应用"></div><div class="table-wrap"><table><thead><tr><th>应用</th><th>版本</th><th>UID</th><th>操作</th></tr></thead><tbody id="app-rows">${appRows('')}</tbody></table></div>`)+panel('当前页面',`<div class="panel-body"><dl class="key-value"><dt>包名</dt><dd>${state.app.pkg}</dd><dt>Activity</dt><dd>.MainActivity</dd><dt>任务 / PID</dt><dd>task #184 · 12480</dd></dl><div class="toolbar" style="margin-top:18px">${button('查看进程','processes')}${button('停止应用','stop-app')}${button('重启应用','restart-app')}${button('权限管理','permissions')}${button('卸载应用','uninstall','danger')}${button('清除应用数据','clear-data','danger')}</div></div>`);}
function appRows(query){return apps.filter(a=>(a.name+a.pkg).toLowerCase().includes(query.toLowerCase())).map(a=>`<tr><td>${esc(a.name)} ${a.pkg===state.app.pkg?'<span class="tag">当前</span>':''}<small>${a.pkg}</small></td><td class="mono">${a.version}</td><td class="mono">${a.uid}</td><td><div class="table-actions"><button class="small-button" data-app="${apps.indexOf(a)}">选用</button><button class="small-button" data-start-app="${apps.indexOf(a)}">启动</button></div></td></tr>`).join('')||'<tr><td colspan="4">没有匹配的应用</td></tr>';}
function schemaPage(){return heading('schema','保留 URI 原文。收藏、编辑、执行，都在同一处完成。')+`<div class="columns"><div>${panel('打开 schema',`<form id="schema-form" class="panel-body"><div class="toolbar" style="margin-bottom:20px"><span class="tag">VIEW INTENT</span><span class="muted" style="font-size:11px">目标：${esc(state.device.name)} · ${state.device.serial}</span><span class="spacer"></span><button type="button" class="text-button" data-action="schema">更换设备</button></div><div class="field"><label for="schema-uri">Schema / URI</label><input id="schema-uri" value="${esc(state.schema)}" placeholder="demo://product/detail?id=1024&source=dev" spellcheck="false" autocomplete="off"><small>Enter 执行 · ↑/↓ 恢复历史 · 长文本随光标横向滚动</small></div><div class="form-grid"><div class="field"><label for="schema-package">目标应用</label><select id="schema-package"><option value="${state.app.pkg}">${state.app.name} · ${state.app.pkg}</option><option value="">交给系统解析</option></select></div><div class="field"><label for="schema-action">Action</label><select id="schema-action"><option>android.intent.action.VIEW</option></select></div></div><div class="toolbar" style="margin-bottom:18px"><button type="button" class="text-button" data-fill="demo://product/detail?id=1024&source=dev">填入详情示例</button><span class="muted">/</span><button type="button" class="text-button" data-fill="unhandled://missing">填入无法解析示例</button></div><div class="form-footer"><small id="schema-validation">在当前设备上打开，使用原始 URI。</small><div class="toolbar"><button type="button" data-action="save-favorite">☆ 收藏</button><button type="submit" class="primary">打开页面 ↗</button></div></div></form>`,'/schema')}${panel('Activity / Intent',`<div class="panel-body"><p class="muted" style="font-size:11px;margin-bottom:14px">启动指定组件，或发送带类型参数的调试 Intent。</p><div class="toolbar">${button('配置 Intent','intent')}${button('解析当前 URI','resolve-uri')}</div></div>`)}${resultPanel()}</div><div>${panel('收藏的页面',state.favorites.map((f,i)=>`<button class="action-row" data-fill="${esc(f.uri)}"><span class="action-icon">☆</span><span style="min-width:0"><strong>${esc(f.name)}</strong><small class="mono" style="max-width:210px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(f.uri)}</small></span></button>`).join(''),'SAVED')}${panel('最近提交',state.schemaHistory.length?state.schemaHistory.slice().reverse().slice(0,5).map(uri=>`<button class="action-row" data-fill="${esc(uri)}"><span class="mono cyan">↶</span><span class="mono" style="font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(uri)}</span></button>`).join(''):'<div class="result-placeholder">还没有本次会话的 schema 历史。<br>执行后，可直接按 ↑ 恢复。</div>','THIS SESSION')}<div class="notice info">历史重执行使用当前选中设备。切换设备后，上方目标信息会同步更新。</div></div></div>`;}
const logEntries=[['14:32:01.184','I','ActivityTaskManager','START u0 com.example.app/.MainActivity'],['14:32:01.210','D','AppLifecycle','MainActivity onResume'],['14:32:01.246','I','Network','GET /api/products · 200 · 42ms'],['14:32:02.014','D','Router','open product/detail?id=1024'],['14:32:02.108','W','Choreographer','Skipped 3 frames. Check main thread work.'],['14:32:02.116','I','Product','Detail loaded · product_id=1024'],['14:32:03.428','E','AndroidRuntime','FATAL EXCEPTION: main'],['14:32:03.429','E','AndroidRuntime','java.lang.IllegalStateException: view is detached'],['14:32:03.430','E','AndroidRuntime','at com.example.app.ProductView.bind(ProductView.kt:84)'],['14:32:04.020','I','Process','Process restarted · PID 12842']];
function logRows(){return logEntries.filter(l=>(state.logLevel==='all'||l[1]===state.logLevel)&&l.join(' ').toLowerCase().includes(state.logQuery.toLowerCase())).map(l=>`<div class="log-row ${l[1]==='E'?'error':l[1]==='W'?'warning':''}"><span class="time">${l[0]}</span><span class="log-level">${l[1]}</span><span class="log-tag">${l[2]}</span><span class="message">${esc(l[3])}</span></div>`).join('')||'<div class="empty">没有匹配日志，尝试调整筛选条件。</div>';}
function logPage(){return heading('logs','按当前应用与进程查看，保留异常上下文。',`<div class="toolbar">${button('开始采集','start-log','primary')}${button('导出片段','export-log')}</div>`)+panel('应用日志',`<div class="log-controls"><span class="tag">${state.app.pkg}</span><select id="log-level" aria-label="日志级别"><option value="all">全部级别</option>${['D','I','W','E'].map(l=>`<option ${state.logLevel===l?'selected':''}>${l}</option>`).join('')}</select><input id="log-query" placeholder="关键词、Tag 或堆栈…" value="${esc(state.logQuery)}" aria-label="筛选日志"><button class="small-button" data-action="pause-log">${state.logPaused?'继续滚动':'暂停滚动'}</button></div><div class="log-output" id="log-output">${logRows()}</div><div class="coverage">${state.logPaused?'滚动已暂停':'自动滚动'} · 主进程 + :worker · 采样窗口 14:32:01—14:32:04 · 示例日志</div>`)+`<div class="columns"><div>${panel('异常线索',`<button class="action-row" data-action="crash"><span class="action-icon red">!</span><span><strong>IllegalStateException</strong><small>主线程 · ProductView.kt:84 · 14:32:03</small></span><span class="tag failed">CRASH</span></button>`)}</div><div>${resultPanel()}</div></div>`;}
function mediaPage(){const running=state.tasks.find(t=>t.type==='record'&&t.status==='running');return heading('media','截图与视频按设备保存，停止录制后再完成导出。')+`<div class="columns"><div>${panel('画面采集',`<div class="panel-body"><div class="device-summary"><div class="device-illustration"></div><div><h3>${esc(state.device.name)}</h3><p class="page-subtitle">1080 × 2400 · portrait</p></div></div><div class="field" style="margin-top:24px"><label for="media-output">本地输出目录</label><input id="media-output" value="./captures/"></div><div class="toolbar">${button('▣ 截取当前画面','screenshot','primary')}${running?`<button data-stop="${running.id}">■ 停止并保存录屏</button>`:button('● 开始录屏','record')}</div><div class="notice info">录屏停止后完成视频收尾和导出。安全窗口的画面可能无法采集。</div></div>`)}${panel('界面检查',`<div class="panel-body"><p class="muted" style="font-size:12px;margin-bottom:16px">导出当前页面的控件结构，按文本、资源 ID 和坐标定位。</p><div class="toolbar">${button('导出 UI XML','ui-xml')}${button('返回键','key-back')}${button('主页键','key-home')}</div></div>`)}</div><div>${resultPanel()}${panel('最近产物',`<div class="artifact"><span class="artifact-icon">PNG</span><div><h3>pixel8-143008.png</h3><small>1080 × 2400 · DEMO123</small><small>示例产物</small></div></div>`)}</div></div>`;}
function fileRows(){const nested=state.folder.endsWith('/debug/');const entries=nested?[['..','目录','file-parent'],['session.json','3.1 KB',''],['trace.log','128 KB','']]:[['debug/','目录','folder'],['sample.json','2.4 KB',''],['demo.apk','24.8 MB','']];return entries.map(([name,size,action])=>`<tr><td>${action?'▱':'▤'} ${name}</td><td class="mono">${size}</td><td><button class="small-button" ${action?`data-action="${action}"`:`data-filepull="${name}"`}>${action?'打开':'拉取'}</button></td></tr>`).join('');}
function filesPage(){return heading('files','浏览 shell 可访问目录，文件传输始终显示来源与目标。',button('＋ 上传文件','push'))+`<div class="columns"><div>${panel('设备文件',`<div class="file-path" id="file-path">${esc(state.folder)}</div><div class="table-wrap"><table><thead><tr><th>名称</th><th>大小</th><th>操作</th></tr></thead><tbody>${fileRows()}</tbody></table></div>`)}${panel('应用数据',`<div class="panel-body"><dl class="key-value"><dt>应用</dt><dd>${state.app.pkg}</dd><dt>可用能力</dt><dd class="${state.app.debug?'green':'amber-text'}">${state.app.debug?'Debug · run-as 可用（示例）':'当前应用不支持 run-as'}</dd></dl><div class="toolbar" style="margin-top:18px">${button('导出 SharedPreferences','prefs')}${button('数据库导出','database')}</div></div>`)}</div><div>${resultPanel()}<div class="notice">数据库导出需确认快照方式。运行中的 SQLite 文件不能只拉取单个主文件作为一致备份。</div></div></div>`;}
function networkPage(){return heading('network','管理当前设备的端口映射，连接电脑上的开发服务。',button('＋ 添加映射','add-mapping','primary'))+panel('端口映射',`<div class="table-wrap"><table><thead><tr><th>方向</th><th>设备端口</th><th>电脑端口</th><th>设备</th><th>操作</th></tr></thead><tbody>${state.mappings.filter(m=>m.device===state.device.serial).map(m=>`<tr><td><span class="cyan mono">${m.direction.toUpperCase()}</span><small>${m.direction==='reverse'?'设备 → 电脑':'电脑 → 设备'}</small></td><td class="mono">tcp:${m.remote}</td><td class="mono">tcp:${m.local}</td><td class="mono">${m.device}</td><td><button class="small-button" data-remove-mapping="${state.mappings.indexOf(m)}">删除此映射</button></td></tr>`).join('')||'<tr><td colspan="5">当前设备没有端口映射。</td></tr>'}</tbody></table></div>`)+`<div class="columns"><div>${panel('常用联调',`${actionRow('⇄','Metro / 本地前端','设备 8081 → 电脑 8081','reverse','preset-8081')}${actionRow('⇄','本地 API 服务','设备 8080 → 电脑 8080','reverse','preset-8080')}`)}${panel('系统代理',`<div class="panel-body"><p class="muted" style="font-size:12px;margin-bottom:16px">当前：未设置代理</p>${button('设置代理','proxy')}<small style="display:block;margin-top:14px">是否采用系统代理由应用网络库决定。</small></div>`)}</div><div>${resultPanel()}</div></div>`;}
function diagnosticPage(){return heading('diagnostics','记录有来源的采样指标，把排查材料整理到一起。')+`<div class="columns"><div>${panel('应用内存',`<div class="metric-row"><div><small>TOTAL PSS</small><strong>148.6 <span style="font-size:12px">MB</span></strong><small>14:30:08 · 示例快照</small></div><div><small>JAVA HEAP</small><strong>32.4 <span style="font-size:12px">MB</span></strong><small>PID 12480</small></div></div><div class="panel-body toolbar" style="border-top:1px solid var(--line)">${button('采集内存快照','memory','primary')}${button('查看进程','processes')}</div>`)}${panel('启动与性能',`${actionRow('↗','测量启动耗时','记录 am start -W 的系统返回值','startup','startup')}${actionRow('≋','采集 Perfetto','选择采集时长与场景预设','perfetto','perfetto')}`)}<div class="notice">系统启动耗时不代表首帧或完全可交互时间。此处不生成综合性能评分。</div></div><div>${panel('系统环境',`<div class="panel-body"><p class="muted" style="font-size:11px;margin-bottom:14px">调整分辨率、密度与动画倍率，保留原值便于恢复。</p>${button('配置系统环境','environment')}</div>`)}${panel('问题取证',`<div class="panel-body"><h3>把一次复现整理成问题包</h3><p class="page-subtitle">设备与应用摘要、日志片段及你选择的附件。</p><div class="toolbar" style="margin-top:18px">${button('收集问题包','bundle','primary')}${button('完整 bugreport','bugreport')}</div></div>`)}${resultPanel()}</div></div>`;}
function workflowPage(){return heading('workflows','把重复的开发步骤组合起来，每一步都有执行结果。')+`<div class="columns"><div>${panel('安装 → 启动 → 查看日志',`<div class="panel-body"><div class="steps"><div class="step"><span class="step-index">01</span><div>选择 APK 与目标设备<small>覆盖升级，保留已有应用数据</small></div></div><div class="step"><span class="step-index">02</span><div>安装后启动应用<small>显示系统安装和启动结果</small></div></div><div class="step"><span class="step-index">03</span><div>开始采集应用日志<small>复现后停止，保留日志产物</small></div></div></div>${button('配置并运行','workflow-install','primary')}</div>`)}${panel('更多工作流',`${actionRow('↗','抓日志并打开 schema','先采集，再跳转到目标页面','workflow','workflow-schema')}${actionRow('⇄','端口映射并启动应用','配置本地服务后完成启动','workflow','workflow-network')}`)}</div><div>${panel('执行方式',`<div class="panel-body"><p class="muted" style="font-size:12px;line-height:2">每次运行先核对设备和应用。某一步失败时停在该步骤，保留已有结果，并允许修改参数后重新运行。</p><div class="notice info">停止任务只清理本次创建的资源；不会删除其他工具的端口映射。</div></div>`)}${resultPanel()}</div></div>`;}
function favoritePage(){return heading('favorites','显式收藏常用参数。打开收藏时先填入编辑框，由你确认执行。',button('＋ 新增收藏','new-favorite','primary'))+panel('Schema 收藏',state.favorites.map((f,i)=>`<div class="action-row"><span class="action-icon">☆</span><span style="min-width:0;flex:1"><strong>${esc(f.name)}</strong><small class="mono" style="overflow-wrap:anywhere">${esc(f.uri)}</small></span><div class="toolbar"><button class="small-button" data-favorite="${i}">填入并编辑</button><button class="small-button" data-delete-favorite="${i}" aria-label="删除收藏 ${esc(f.name)}">×</button></div></div>`).join('')||'<div class="empty">还没有收藏，添加一个常用 schema。</div>')+'<p class="muted" style="font-size:11px">预览中的收藏仅在本次页面打开期间保留。正式功能将按设计提供显式保存。</p>';}
function historyPage(){return heading('history','查看本次会话的操作，重执行时使用当前设备。')+panel('执行清单',state.history.length?`<div class="table-wrap"><table><thead><tr><th>时间</th><th>操作 / 参数</th><th>原设备</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.history.slice().reverse().map(h=>`<tr><td class="mono">${h.time}</td><td>${esc(h.name)}<small style="max-width:370px;overflow:hidden;text-overflow:ellipsis">${esc(h.value)}</small></td><td class="mono">${h.device}</td><td>${tag(h.status)}</td><td><button class="small-button" data-replay="${state.history.indexOf(h)}">恢复输入</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">本次会话还没有执行记录。<br>先打开一个 schema，或执行一次截图。</div>')+'<div class="notice info">普通输入框中的 ↑/↓ 同样可以切换 schema 历史，向下回到最新位置时恢复草稿。</div>';}
function taskPage(){return heading('tasks','长任务的启动、停止和文件收尾，都有明确状态。')+panel('任务清单',state.tasks.map(t=>`<div class="action-row"><span class="action-icon">${t.type==='record'?'●':t.type==='log'?'≡':'▤'}</span><span style="min-width:0;flex:1"><strong>${esc(t.name)}　${tag(t.status)}</strong><small class="mono" style="overflow-wrap:anywhere">${t.device} · ${esc(t.artifact)}</small></span>${t.status==='saving'?'<button class="small-button" disabled>保存中…</button>':t.status==='running'?`<button class="small-button" data-stop="${t.id}">停止并保存</button>`:`<button class="small-button" data-artifact="${t.id}">查看产物</button>`}</div>`).join('')||'<div class="empty">暂无任务</div>');}
const renderers={home,devices:devicePage,apps:appPage,schema:schemaPage,logs:logPage,media:mediaPage,files:filesPage,network:networkPage,diagnostics:diagnosticPage,workflows:workflowPage,favorites:favoritePage,history:historyPage,tasks:taskPage};

function openModal(title,content,eyebrow='ACTION'){if($('#modal').open)$('#modal').close();$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-content').innerHTML=content;$('#modal').showModal();}
function chooseDevice(next){
  const available=availableDevices();pendingDeviceAction=next;
  if(!available.length){openModal('没有可用设备','<div class="notice">请连接设备并允许 USB 调试，或配置无线连接。</div><div class="dialog-actions"><button data-close>返回</button><button class="primary" data-nav="devices">查看设备</button></div>','NO DEVICE');return;}
  if(available.length===1){state.device=available[0];updateContext();pendingDeviceAction=null;next();return;}
  pickerIndex=Math.max(0,available.findIndex(d=>d.serial===state.device.serial));
  openModal('选择目标设备',`<p class="picker-description">检测到 ${available.length} 台可用设备。确认后继续操作。</p><div id="device-options">${available.map((d,i)=>`<button class="picker-option ${i===pickerIndex?'selected':''}" data-pick-device="${i}" aria-pressed="${i===pickerIndex}"><span class="radio"></span><span><strong>${d.name}</strong><small>${d.serial} · ${d.os}</small></span><span class="tag">${d.kind}</span></button>`).join('')}</div><div class="disabled-device"><span>▯</span>待授权设备<small>DEMO-LOCKED · 不可选择</small></div><div class="dialog-actions"><button data-close>取消</button><button class="primary" id="confirm-device">选择并继续 ↵</button></div>`,'SELECT DEVICE');
}
function selectDeviceIndex(index){pickerIndex=index;document.querySelectorAll('[data-pick-device]').forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-pressed',String(i===index));});}
function confirmDevice(){state.device=availableDevices()[pickerIndex];const next=pendingDeviceAction;pendingDeviceAction=null;$('#modal').close();updateContext();next?.();}
function showResult(index){const r=state.results[index];openModal(r.name,`<div class="toolbar" style="margin-bottom:14px">${tag(r.status)}<span class="mono muted">${r.device} · ${r.time} · ${r.duration}</span></div><pre class="result-output">${esc(r.output)}</pre><details style="margin-top:18px"><summary class="muted">查看实际命令</summary><pre class="result-output">${esc(r.command)}</pre></details><div class="dialog-actions"><button data-close>关闭</button><button class="primary" data-action="download-result">导出结果</button></div>`,'EXECUTION RESULT');}
function execute(name,command,output,options={}){
  const device=state.device.serial;const failed=!!options.failed;
  const r={name,command,output,device,status:failed?'failed':'success',time:time(),duration:options.duration||'126 ms'};
  state.results.unshift(r);state.history.push({name,value:options.value||command,kind:options.kind||'command',device,status:r.status,time:r.time});
  if(options.artifact)state.tasks.unshift({id:Date.now(),name,device,status:'success',artifact:options.artifact,type:options.type||'file'});
  refresh();notify(`${name}${failed?'失败，查看结果':'已完成'} · ${state.device.name}`);
}
function schemaExecute(value){
  const uri=value.trim();if(!uri){notify('请输入 schema');$('#schema-validation')?.classList.add('red');return;}
  state.schema=uri;state.schemaHistory.push(uri);state.historyIndex=null;dockSchemaMode=false;commandInput.value='';$('#command-mode').textContent='COMMAND';
  const failed=uri.startsWith('unhandled:');execute('打开 schema',`adb -s ${state.device.serial} shell am start -W -a android.intent.action.VIEW -d ${JSON.stringify(uri)}`,failed?'Error: Activity not started, unable to resolve Intent\n没有应用能够处理这个 URI。请检查协议和目标应用。':`Status: ok\nActivity: ${state.app.pkg}/.ProductActivity\nTotalTime: 184\nComplete`,{failed,kind:'schema',value:uri,duration:'184 ms'});
}
function startTask(type){if(state.tasks.some(t=>t.status==='running'&&t.device===state.device.serial&&t.type===type)){notify('当前设备已有同类任务，请先停止');showPage('tasks');return;}const recording=type==='record';state.tasks.unshift({id:Date.now(),name:recording?'设备录屏':'应用日志采集',device:state.device.serial,status:'running',artifact:`${recording?'recordings':'logs'}/${state.device.serial}-${Date.now()}.${recording?'mp4':'log'}`,type});refresh();notify(`${recording?'录屏':'日志采集'}已开始`);}
function stopTask(id){const t=state.tasks.find(t=>t.id===Number(id));if(!t||t.status!=='running')return;t.status='saving';refresh();notify('正在停止并保存…');setTimeout(()=>{t.status='success';refresh();notify('已停止，产物已保存');},450);}
function favoriteDialog(){const uri=$('#schema-uri')?.value||state.schema;openModal('收藏 schema',`<form id="favorite-form"><div class="field"><label for="favorite-name">名称</label><input id="favorite-name" placeholder="例如：商品详情" required></div><div class="field"><label for="favorite-uri">Schema</label><input id="favorite-uri" value="${esc(uri)}" placeholder="demo://…" required></div><div class="dialog-actions"><button type="button" data-close>取消</button><button class="primary" type="submit">保存收藏</button></div></form>`,'SAVE FAVORITE');}
function installDialog(workflow=false){openModal(workflow?'安装并启动应用':'安装 APK',`<form id="install-form" data-workflow="${workflow}"><div class="notice info">目标：${esc(target())}<br>覆盖升级保留数据；签名不兼容时停止，不自动卸载。</div><div class="field"><label for="apk-path">本地 APK 路径</label><input id="apk-path" value="./build/outputs/apk/debug/app-debug.apk" required></div><label class="toggle-label"><input type="checkbox" id="launch-after" ${workflow?'checked':''}> 安装完成后启动应用</label><div class="dialog-actions"><button type="button" data-close>取消</button><button type="submit" class="primary">安装${workflow?'并启动':''}</button></div></form>`,'INSTALL APPLICATION');}
function mappingDialog(preset=''){openModal('添加端口映射',`<form id="mapping-form"><p class="picker-description">目标设备：${esc(state.device.name)} · ${state.device.serial}</p><div class="field"><label for="mapping-direction">方向</label><select id="mapping-direction"><option value="reverse">Reverse · 设备访问电脑</option><option value="forward">Forward · 电脑访问设备</option></select></div><div class="form-grid"><div class="field"><label for="device-port">设备端口</label><input id="device-port" type="number" min="1" max="65535" value="${preset||'8080'}" required></div><div class="field"><label for="host-port">电脑端口</label><input id="host-port" type="number" min="1" max="65535" value="${preset||'8080'}" required></div></div><div class="dialog-actions"><button type="button" data-close>取消</button><button type="submit" class="primary">添加映射</button></div></form>`,'PORT MAPPING');}
function confirmDanger(action){const labels={'clear-data':'清除应用数据',reboot:'重启设备',uninstall:'卸载应用',database:'停止应用并导出数据库'};openModal(labels[action],`<p class="picker-description">请核对本次操作的目标。</p><dl class="key-value"><dt>设备</dt><dd>${state.device.name} / ${state.device.serial}</dd><dt>应用</dt><dd>${state.app.pkg}</dd><dt>用户</dt><dd>0</dd></dl><div class="notice">${['clear-data','uninstall'].includes(action)?'这会删除该应用的本地数据，无法撤销。':action==='database'?'将停止当前应用后采集可访问数据库文件。应用内未保存的状态可能丢失。':'这会中断该设备上的所有调试连接和运行任务。'}</div><div class="dialog-actions"><button data-close>取消</button><button class="danger" data-confirm-danger="${action}">确认${labels[action]}</button></div>`,'CONFIRM TARGET');}
function downloadResult(){const r=state.results[0];const blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mylogger-demo-result.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('已导出演示结果');}
function requestAction(action){
  if(action==='push'){chooseDevice(()=>openModal('yazi · 选择本地文件',`<p class="picker-description">目标设备：${esc(state.device.name)} · ${esc(state.device.serial)}</p><div class="notice info">终端会直接调用本机 yazi。此处模拟选文件，取消后返回工作台。</div><button class="picker-option" data-push-file="/Users/developer/sample.json"><span>sample.json</span><small>/Users/developer/sample.json</small></button><button class="picker-option" data-push-file="/Users/developer/开发资料.txt"><span>开发资料.txt</span><small>/Users/developer/开发资料.txt</small></button><div class="dialog-actions"><button data-close>取消</button></div>`,'LOCAL FILE'));return;}
  if(!availableDevices().length&&!['refresh-devices','pair','connect','new-favorite'].includes(action)){chooseDevice(()=>{});return;}
  const direct={schema:()=>{showPage('schema');$('#schema-uri').focus();},install:()=>installDialog(),screenshot:()=>execute('设备截图',`adb -s ${state.device.serial} exec-out screencap -p`,'PNG saved\n1080 × 2400\n./captures/pixel8-latest.png',{artifact:'./captures/pixel8-latest.png',type:'image'}),logs:()=>showPage('logs'),network:()=>showPage('network'),'start-log':()=>startTask('log'),record:()=>startTask('record'),'workflow-install':()=>installDialog(true),'workflow-schema':()=>{startTask('log');showPage('schema');},'workflow-network':()=>mappingDialog('8080')};
  if(direct[action]){chooseDevice(direct[action]);return;}
  if(action==='intent'){openModal('配置 Intent',`<form id="intent-form"><div class="field"><label for="intent-component">Component</label><input id="intent-component" value="${state.app.pkg}/.MainActivity" required></div><div class="field"><label for="intent-kind">操作类型</label><select id="intent-kind"><option value="activity">启动 Activity</option><option value="broadcast">发送 Broadcast</option><option value="service">启动 Service</option></select></div><div class="field"><label for="intent-extra">Extra · String</label><input id="intent-extra" placeholder="例如：source=debug"></div><div class="notice info">目标组件须允许外部访问；系统权限和后台限制仍然适用。</div><div class="dialog-actions"><button type="button" data-close>取消</button><button class="primary">发送 Intent</button></div></form>`,'INTENT EDITOR');return;}
  if(action==='resolve-uri'){execute('解析跳转目标','cmd package query-activities',`Matched activity:\n${state.app.pkg}/.ProductActivity`);return;}
  if(action==='permissions'){openModal('应用权限',`<form id="permissions-form"><p class="picker-description">${state.app.pkg} · user 0</p>${['相机 CAMERA','麦克风 RECORD_AUDIO','通知 POST_NOTIFICATIONS'].map((name,i)=>`<label class="toggle-label" style="margin:16px 0"><input type="checkbox" ${i===2?'checked':''}>${name}</label>`).join('')}<div class="dialog-actions"><button type="button" data-close>取消</button><button class="primary">应用权限设置</button></div></form>`,'RUNTIME PERMISSIONS');return;}
  if(action==='environment'){openModal('系统环境',`<form id="environment-form"><div class="form-grid"><div class="field"><label for="density">显示密度（dpi）</label><input id="density" type="number" value="420" min="120" required></div><div class="field"><label for="animation">动画倍率</label><select id="animation"><option>1.0</option><option>0.5</option><option>0.0</option></select></div></div><div class="notice info">修改前记录当前值。恢复操作只恢复本工具修改的项目。</div><div class="dialog-actions"><button type="button" data-action="restore-environment">恢复原值</button><button type="button" data-close>取消</button><button class="primary">应用设置</button></div></form>`,'DEVICE ENVIRONMENT');return;}
  if(action==='restore-environment'){$('#modal').close();execute('恢复系统环境','restore saved density + animation','Original settings restored');return;}
  const simple={
    'stop-app':['停止应用',`am force-stop ${state.app.pkg}`,'Application stopped'],
    'restart-app':['重启应用',`am force-stop ${state.app.pkg}; am start -n ${state.app.pkg}/.MainActivity`,'Status: ok\nActivity: .MainActivity\nComplete'],
    'ui-xml':['导出 UI XML','uiautomator dump','Hierarchy saved\n./captures/window.xml'],
    'key-back':['返回键','input keyevent 4','Key event delivered'],
    'key-home':['主页键','input keyevent 3','Key event delivered'],
    memory:['内存快照',`dumpsys meminfo ${state.app.pkg}`,'TOTAL PSS: 152166 KB\nJava Heap: 33177 KB\nNative Heap: 48120 KB\nPID: 12480'],
    startup:['启动耗时',`am start -W -n ${state.app.pkg}/.MainActivity`,'Status: ok\nThisTime: 184\nTotalTime: 184\nWaitTime: 196\n本次未先 force-stop，不标记为冷启动。'],
    processes:['应用进程',`pidof ${state.app.pkg}`,'12480 12842\nmain · 12480\n:worker · 12842'],
    pull:['拉取文件','pull /sdcard/Download/sample.json ./downloads/','1 file pulled · 2.4 KB\n./downloads/sample.json'],
    'pull-apk':['拉取 APK','pull /sdcard/Download/demo.apk ./downloads/','1 file pulled · 24.8 MB\n./downloads/demo.apk'],
  };
  if(simple[action]){const [name,cmd,out]=simple[action];execute(name,`adb -s ${state.device.serial} ${cmd}`,out);return;}
  if(action==='new-favorite'||action==='save-favorite'){favoriteDialog();return;}
  if(action==='add-mapping'||action.startsWith('preset-')){mappingDialog(action.startsWith('preset-')?action.slice(7):'');return;}
  if(['clear-data','reboot','database','uninstall'].includes(action)){confirmDanger(action);return;}
  if(action==='pause-log'){state.logPaused=!state.logPaused;refresh();return;}
  if(action==='refresh-devices'){notify('设备列表已刷新');refresh();return;}
  if(action==='copy-device'){navigator.clipboard?.writeText(`${state.device.name}\n${state.device.serial}\n${state.device.os}`).then(()=>notify('设备信息已复制')).catch(()=>notify('当前浏览器不允许复制'));return;}
  if(action==='download-result'||action==='export-log'){downloadResult();return;}
  if(action==='crash'){openModal('Crash 上下文',`<pre class="result-output">${esc(logEntries.filter(l=>l[1]==='E').map(l=>l.join('  ')).join('\n'))}</pre><div class="dialog-actions"><button data-close>关闭</button><button data-action="bundle" class="primary">收集问题包</button></div>`,'CRASH / EVIDENCE');return;}
  if(action==='folder'||action==='file-parent'){state.folder=action==='folder'?'/sdcard/Download/debug/':'/sdcard/Download/';refresh();return;}
  if(action==='prefs'){if(!state.app.debug){notify('目标应用不支持 run-as');return;}execute('导出应用配置',`adb -s ${state.device.serial} shell run-as ${state.app.pkg}`,'Exported shared_prefs\n./exports/shared-prefs.json',{artifact:'./exports/shared-prefs.json'});return;}
  if(action==='bundle'){openModal('收集问题包',`<form id="bundle-form"><p class="picker-description">${esc(target())}</p><div class="field"><label for="issue-note">问题描述</label><textarea id="issue-note" placeholder="例如：从商品详情返回时闪退"></textarea></div><div class="toolbar"><label class="toggle-label"><input type="checkbox" checked>设备与应用信息</label><label class="toggle-label"><input type="checkbox" checked>日志片段</label><label class="toggle-label"><input type="checkbox">附加截图</label></div><div class="notice info">本地保存，不自动上传。</div><div class="dialog-actions"><button type="button" data-close>取消</button><button class="primary">生成问题包</button></div></form>`,'COLLECT EVIDENCE');return;}
  const formNames={connect:['连接无线设备','调试地址','192.168.1.80:40123','连接名称','Pixel 无线调试'],pair:['无线配对','配对地址','192.168.1.80:37123','配对码','123456'],proxy:['设置代理','代理地址','192.168.1.10','端口','8888'],perfetto:['采集 Perfetto','采集时长（秒）','10','场景','应用启动'],bugreport:['完整 bugreport','输出目录','./reports/','文件名','bugreport.zip']};
  if(formNames[action]){const [title,l1,v1,l2,v2]=formNames[action];openModal(title,`<form id="generic-form" data-kind="${action}"><p class="picker-description">目标：${esc(state.device.name)} · ${state.device.serial}</p><div class="field"><label for="generic-first">${l1}</label><input id="generic-first" value="${v1}" required></div><div class="field"><label for="generic-second">${l2}</label><input id="generic-second" value="${v2}" required></div><div class="dialog-actions"><button type="button" data-close>取消</button><button class="primary">${title}</button></div></form>`,'CONFIGURE');return;}
}

const commands=[['schema','打开 schema','页面跳转、收藏与历史','/schema','↗'],['install','安装 APK','覆盖安装并保留数据','/install','↓'],['logs','查看应用日志','筛选、异常、导出','/log','≡'],['screenshot','截取设备画面','PNG 图片','/screenshot','▣'],['record','开始录屏','手动停止后保存','/record','●'],['network','管理端口映射','reverse / forward','/reverse','⇄'],['memory','内存快照','当前应用 meminfo','/memory','⌁'],['bundle','收集问题包','日志、环境与附件','/bundle','▤'],['devices','查看设备','连接与无线调试','/device','▯']];
commands.push(...pages.filter(p=>!commands.some(c=>c[0]===p[0])).map(p=>[p[0],p[1],p[3],'/'+p[0],p[2]]));
function renderPalette(){const q=$('#palette-input').value.trim().replace(/^\//,'').toLowerCase();paletteItems=commands.filter(c=>c.join(' ').toLowerCase().includes(q));paletteIndex=Math.min(paletteIndex,Math.max(0,paletteItems.length-1));$('#palette-results').innerHTML=paletteItems.map((c,i)=>`<button role="option" aria-selected="${i===paletteIndex}" class="palette-item ${i===paletteIndex?'selected':''}" data-palette="${i}"><span>${c[4]}</span><span><strong>${c[1]}</strong><small>${c[2]}</small></span><code>${c[3]}</code></button>`).join('')||'<div class="empty">没有匹配的操作，试试“日志”或“schema”。</div>';}
function openPalette(initial=''){if($('#modal').open)return;$('#palette').showModal();$('#palette-input').value=initial;paletteIndex=0;renderPalette();$('#palette-input').focus();}
function choosePalette(index){const c=paletteItems[index];if(!c)return;$('#palette').close();commandInput.value='';if(['schema','logs','network'].includes(c[0]))requestAction(c[0]);else if(renderers[c[0]])showPage(c[0]);else requestAction(c[0]);}
function recall(input,older){if(!state.schemaHistory.length)return;if(older){if(state.historyIndex===null){state.draft=input.value;state.historyIndex=state.schemaHistory.length-1;}else state.historyIndex=Math.max(0,state.historyIndex-1);}else{if(state.historyIndex===null)return;state.historyIndex=state.historyIndex+1<state.schemaHistory.length?state.historyIndex+1:null;}input.value=state.historyIndex===null?state.draft:state.schemaHistory[state.historyIndex];input.setSelectionRange(input.value.length,input.value.length);input.scrollLeft=input.scrollWidth;if(input.id==='schema-uri')state.schema=input.value;else{dockSchemaMode=state.historyIndex!==null;$('#command-mode').textContent=dockSchemaMode?'SCHEMA → '+state.device.name:'COMMAND';}}
function submitDock(){const value=commandInput.value.trim();if(!value)return;if(dockSchemaMode||(!value.startsWith('/')&&value.includes('://'))){schemaExecute(value);return;}const cmd=commands.find(c=>c[3].toLowerCase()===value.toLowerCase()||(value==='/打开schema'&&c[0]==='schema'));if(cmd){commandInput.value='';if(cmd[0]==='devices')showPage('devices');else requestAction(cmd[0]);}else openPalette(value);}

document.addEventListener('click',e=>{
  const nav=e.target.closest('[data-nav]');if(nav){if($('#modal').open)$('#modal').close();if(nav.dataset.nav==='schema')requestAction('schema');else showPage(nav.dataset.nav);return;}
  const act=e.target.closest('[data-action]');if(act){requestAction(act.dataset.action);return;}
  if(e.target.closest('[data-close]')||e.target.closest('#modal-close')){$('#modal').close();pendingDeviceAction=null;return;}
  const pick=e.target.closest('[data-pick-device]');if(pick){selectDeviceIndex(Number(pick.dataset.pickDevice));return;}
  if(e.target.closest('#confirm-device')){confirmDevice();return;}
  const pushFile=e.target.closest('[data-push-file]');if(pushFile){openModal('上传文件',`<form id="push-form"><p class="picker-description">目标：${esc(state.device.name)} · ${esc(state.device.serial)}</p><div class="field"><label for="push-local">yazi 已选本地文件</label><input id="push-local" value="${esc(pushFile.dataset.pushFile)}" readonly></div><div class="field"><label for="push-remote">设备目标路径（目录以 / 结尾）</label><input id="push-remote" value="/sdcard/doc/" required></div><p class="picker-description">目录不存在时创建，目录路径自动附加本地文件名。</p><div class="field"><label for="push-overwrite">覆盖已有目标？输入 YES 确认，否则留空</label><input id="push-overwrite"></div><div class="dialog-actions"><button type="button" data-close>取消</button><button class="primary">上传文件</button></div></form>`,'PUSH DESTINATION');return;}
  const select=e.target.closest('[data-select-device]');if(select){state.device=devices[Number(select.dataset.selectDevice)];refresh();notify('当前设备已切换');return;}
  const app=e.target.closest('[data-app]');if(app){state.app=apps[Number(app.dataset.app)];$('#modal').close();refresh();notify('当前应用已切换');return;}
  const start=e.target.closest('[data-start-app]');if(start){state.app=apps[Number(start.dataset.startApp)];execute('启动应用',`adb -s ${state.device.serial} shell am start -n ${state.app.pkg}/.MainActivity`,'Status: ok\nActivity: .MainActivity');return;}
  const filepull=e.target.closest('[data-filepull]');if(filepull){const name=filepull.dataset.filepull;execute('拉取文件',`adb -s ${state.device.serial} pull ${state.folder}${name} ./downloads/`,`1 file pulled\n./downloads/${name}`,{artifact:'./downloads/'+name});return;}
  const fill=e.target.closest('[data-fill]');if(fill){state.schema=fill.dataset.fill;$('#schema-uri').value=state.schema;$('#schema-uri').focus();return;}
  const fav=e.target.closest('[data-favorite]');if(fav){state.schema=state.favorites[Number(fav.dataset.favorite)].uri;requestAction('schema');return;}
  const del=e.target.closest('[data-delete-favorite]');if(del){state.favorites.splice(Number(del.dataset.deleteFavorite),1);refresh();notify('收藏已移除');return;}
  const stop=e.target.closest('[data-stop]');if(stop){stopTask(stop.dataset.stop);return;}
  const artifact=e.target.closest('[data-artifact]');if(artifact){const t=state.tasks.find(t=>t.id===Number(artifact.dataset.artifact));openModal('产物详情',`<dl class="key-value"><dt>名称</dt><dd>${esc(t.name)}</dd><dt>设备</dt><dd>${t.device}</dd><dt>路径</dt><dd>${esc(t.artifact)}</dd><dt>状态</dt><dd>已保存 · 示例产物</dd></dl><div class="dialog-actions"><button data-close>关闭</button></div>`,'ARTIFACT');return;}
  const result=e.target.closest('[data-result]');if(result){showResult(Number(result.dataset.result));return;}
  const rm=e.target.closest('[data-remove-mapping]');if(rm){const m=state.mappings.splice(Number(rm.dataset.removeMapping),1)[0];execute('删除端口映射',`adb -s ${m.device} ${m.direction} --remove tcp:${m.direction==='reverse'?m.remote:m.local}`,'Mapping removed');return;}
  const danger=e.target.closest('[data-confirm-danger]');if(danger){const kind=danger.dataset.confirmDanger;$('#modal').close();if(kind==='reboot'){state.tasks.filter(t=>t.device===state.device.serial&&t.status==='running').forEach(t=>t.status='cancelled');execute('重启设备',`adb -s ${state.device.serial} reboot`,'Reboot requested\n设备将断开并重新连接（演示）');}else execute(kind==='database'?'导出数据库':kind==='uninstall'?'卸载应用':'清除应用数据',`adb -s ${state.device.serial} shell ${kind==='database'?'run-as '+state.app.pkg:(kind==='uninstall'?'pm uninstall ':'pm clear ')+state.app.pkg}`,'Success');return;}
  const replay=e.target.closest('[data-replay]');if(replay){const h=state.history[Number(replay.dataset.replay)];commandInput.value=h.value;dockSchemaMode=h.kind==='schema';$('#command-mode').textContent=dockSchemaMode?'SCHEMA → '+state.device.name:'COMMAND';commandInput.focus();return;}
  const palette=e.target.closest('[data-palette]');if(palette)choosePalette(Number(palette.dataset.palette));
});
document.addEventListener('submit',e=>{
  e.preventDefault();const form=e.target;
  if(form.id==='schema-form'){schemaExecute($('#schema-uri').value);return;}
  if(form.id==='favorite-form'){state.favorites.push({name:$('#favorite-name').value,uri:$('#favorite-uri').value});$('#modal').close();refresh();notify('已保存到收藏');return;}
  if(form.id==='install-form'){const path=$('#apk-path').value;const launch=$('#launch-after').checked;$('#modal').close();execute(launch?'安装并启动':'安装 APK',`adb -s ${state.device.serial} install -r ${JSON.stringify(path)}`,`Performing Streamed Install\nSuccess${launch?'\nStatus: ok\nActivity: .MainActivity':''}`);if(form.dataset.workflow==='true')startTask('log');return;}
  if(form.id==='mapping-form'){const remote=$('#device-port').value,local=$('#host-port').value,direction=$('#mapping-direction').value;if(state.mappings.some(m=>m.device===state.device.serial&&m.direction===direction&&(direction==='reverse'?m.remote===remote:m.local===local))){notify('此来源端口已有映射，请先删除或更换端口');return;}state.mappings.push({device:state.device.serial,remote,local,direction});$('#modal').close();execute('添加端口映射',`adb -s ${state.device.serial} ${direction} tcp:${direction==='reverse'?remote:local} tcp:${direction==='reverse'?local:remote}`,'Mapping added');return;}
  if(form.id==='push-form'){const local=$('#push-local').value,remote=$('#push-remote').value;if(!remote.startsWith('/')){notify('请输入设备上的绝对路径');return;}const destination=remote.endsWith('/')?remote+local.split('/').pop():remote;$('#modal').close();execute('上传文件',`adb -s ${state.device.serial} push ${JSON.stringify(local)} ${JSON.stringify(destination)}`,`1 file pushed\n已上传：${destination}\n示例结果`);return;}
  if(form.id==='bundle-form'){$('#modal').close();execute('收集问题包','collect device + app + selected evidence','Saved locally\nmanifest.json\ndevice.json\napp.json\nlogcat.log',{artifact:'./reports/issue-demo/'});return;}
  if(['intent-form','permissions-form','environment-form'].includes(form.id)){const name=$('#modal-title').textContent;$('#modal').close();execute(name,form.id,'Status: ok\nConfiguration applied');return;}
  if(form.id==='generic-form'){const kind=form.dataset.kind;const name=$('#modal-title').textContent;const first=$('#generic-first').value;$('#modal').close();execute(name,`${kind} ${first}`,kind==='pair'?'Successfully paired\n请继续使用设备上的调试地址连接。':'Complete\n操作已完成（示例结果）',{artifact:kind==='perfetto'?'./captures/perfetto.trace':kind==='bugreport'?'./reports/bugreport.zip':undefined});}
});
document.addEventListener('input',e=>{if(e.target.id==='schema-uri')state.schema=e.target.value;if(e.target.id==='app-filter')$('#app-rows').innerHTML=appRows(e.target.value);if(e.target.id==='log-query'){state.logQuery=e.target.value;$('#log-output').innerHTML=logRows();}});
document.addEventListener('change',e=>{if(e.target.id==='connection-scenario'){state.connectionMode=e.target.value;refresh();}if(e.target.id==='log-level'){state.logLevel=e.target.value;$('#log-output').innerHTML=logRows();}});
document.addEventListener('keydown',e=>{
  if($('#palette').open){if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();paletteIndex=(paletteIndex+(e.key==='ArrowDown'?1:-1)+Math.max(1,paletteItems.length))%Math.max(1,paletteItems.length);renderPalette();$('#palette-results .selected')?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'){e.preventDefault();choosePalette(paletteIndex);}return;}
  if($('#modal').open){if($('#confirm-device')){if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();selectDeviceIndex((pickerIndex+(e.key==='ArrowDown'?1:-1)+availableDevices().length)%availableDevices().length);}if(e.key==='Enter'){e.preventDefault();confirmDevice();}}return;}
  if((e.target.id==='schema-uri'||e.target.id==='command-input')&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();recall(e.target,e.key==='ArrowUp');return;}
  if(e.key==='Enter'&&e.target===commandInput){e.preventDefault();submitDock();return;}
  if(e.key==='Escape'){dockSchemaMode=false;state.historyIndex=null;commandInput.value='';$('#command-mode').textContent='COMMAND';e.target.blur?.();return;}
  if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();openPalette();}
});
$('#search-launch').addEventListener('click',()=>openPalette());
$('#palette-input').addEventListener('input',()=>{paletteIndex=0;renderPalette();});
$('#device-context').addEventListener('click',()=>chooseDevice(()=>refresh()));
$('#app-context').addEventListener('click',()=>openModal('选择当前应用',apps.map((a,i)=>`<button class="picker-option" data-app="${i}"><span class="app-mark">${a.name[0]}</span><span><strong>${a.name}</strong><small>${a.pkg}</small></span><span class="tag">${a.debug?'DEBUG':'SYSTEM'}</span></button>`).join(''),'SELECT APPLICATION'));
commandInput.addEventListener('input',()=>{if(commandInput.value==='/')openPalette();});
$('#command-submit').addEventListener('click',submitDock);
$('#modal').addEventListener('cancel',()=>{pendingDeviceAction=null;});
setInterval(()=>$('#status-clock').textContent=time(),1000);
showPage('home');
if(location.hash==='#schema')requestAction('schema');
